            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "The scientific man does not aim at an immediate result. He does not expect that his advanced ideas will be readily taken up. His work is like that of the planter — for the future. His duty is to lay the foundation for those who are to come, and point the way. He lives and labors and hopes.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "Our virtues and our failings are inseparable, like force and matter. When they separate, man is no more.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "In a crystal we have the clear evidence of the existence of a formative life-principle, and though we cannot understand the life of a crystal, it is none the less a living being.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "Money does not represent such a value as men have placed upon it. All my money has been invested into experiments with which I have made new discoveries enabling mankind to have a little easier life.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "Let the future tell the truth and evaluate each one according to his work and accomplishments. The present is theirs; the future, for which I really worked, is mine.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "The idea of atomic energy is illusionary but it has taken so powerful a hold on the minds, that although I have preached against it for twenty-five years, there are still some who believe it to be realizable.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "I have harnessed the cosmic rays and caused them to operate a motive device.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "Edison was by far the most successful and, probably, the last exponent of the purely empirical method of investigation. Everything he achieved was the result of persistent trials and experiments often performed at random but always attesting extraordinary vigor and resource.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "I hold that space cannot be curved, for the simple reason that it can have no properties. It might as well be said that God has properties. I, for one, refuse to subscribe to such a view.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "Today's scientists have substituted mathematics for experiments, and they wander off through equation after equation, and eventually build a structure which has no relation to reality.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "The scientists from Franklin to Morse were clear thinkers and did not produce erroneous theories. The scientists of today think deeply instead of clearly. One must be sane to think clearly, but one can think deeply and be quite insane.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "Guglielmo Marconi is a good fellow. Let him continue. He is using seventeen of my patents.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "I do not think there is any thrill that can go through the human heart like that felt by the inventor as he sees some creation of the brain unfolding to success … Such emotions make a man forget food, sleep, friends, love, everything.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "The production of artificial food as a means for causing an increase of the human mass naturally suggests itself, but a direct attempt of this kind to provide nourishment does not appear to me rational, at least not for the present. Whether we could thrive on such food is very doubtful.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "It has been argued that the perfection of guns of great destructive power will stop warfare. So I myself thought for a long time, but now I believe this to be a profound mistake. Such developments will greatly modify, but not arrest it.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "The ultimate results of development in these three directions are: first, the burning of coal by a cold process in a battery; second, the efficient utilization of the energy of the ambient medium; and, third the transmission without wires of electrical energy to any distance.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "Aluminium, however, will not stop at downing copper. Before many years have passed it will be engaged in a fierce struggle with iron, and in the latter it will find an adversary not easy to conquer.", Author = "Nikola Tesla" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nikola_Tesla", Text = "A far better way, however, to obtain power would be to avail ourselves of the sun's rays, which beat the earth incessantly and supply energy at a maximum rate of over four million horsepower per square mile.", Author = "Nikola Tesla" },
